sys_variable_value.value:
(function execute(inputs, outputs) {

  var key = gs.getProperty("x_vuram_fcc_kyc_0.Veriff_SS");
  var Crypto = new HMAC_Generation().CryptoJS;

  var hashfront = Crypto.HmacSHA256(inputs.document_front_id ,key);
  outputs.documentfronthash = hashfront.toString(Crypto.enc.Hex);

  var hashback = Crypto.HmacSHA256(inputs.document_back_id ,key);
  outputs.documentbackhash = hashback.toString(Crypto.enc.Hex);

  var hashselfie = Crypto.HmacSHA256(inputs.selfie_video_id ,key);
  outputs.selfiehash = hashselfie.toString(Crypto.enc.Hex);


})(inputs, outputs);

